Method.Source:
[Form]
public class GUPPriceAdjustPriceAttributeGroupEdit extends FormRun
{
    private Common                      argsRecord;
    private RetailPeriodicDiscount      periodicDiscount;
    private RetailPeriodicDiscountLine  periodicDiscountLine;
    private GUPGroupAll                 groupCodeHeader;
    private GUPGroupAll                 groupCodeLine;
    private Query                       inventTablePreviewQuery;
    private Query                       custTablePreviewQuery;
    private Query                       productVariantPreviewQuery;
    private boolean                     addProductvariants = false;
    private boolean                     showPricingGroupHeader = false;
    private boolean                     showPricingGroupHeaderAndLine = false;
    private boolean                     allowEditPricingGroupHeader = true;
    private boolean                     formIsCancelled = false;

}

    public void init()
    {
        argsRecord = element.args().record();

        if (!argsRecord)
        {
            throw error(error::wrongUseOfFunction(funcName()));
        }

        element.identifyArgsRecord();
        element.initMasterRecords();

        super();
        
        element.initFormPricingObjectPreviewQuery();
        element.setPriceAttributeGroupCombinationName();
    }

public void run()
{
    super();
    element.initFormControls();
}

private void identifyArgsRecord()
{
    if (argsRecord is RetailPeriodicDiscountLine)
    {
        element.showPricingGroupHeaderAndLine = true;
    }
    else if (argsRecord is RetailPeriodicDiscount)
    {
        element.showPricingGroupHeader = true;
    }
}

    private void initMasterRecords()
    {
        if (element.showPricingGroupHeaderAndLine)
        {
            periodicDiscountLine = argsRecord;
            periodicDiscount = RetailPeriodicDiscount::findByOfferId(periodicDiscountLine.OfferId);

            if (!periodicDiscount.HeaderPricingRule)
            {
                periodicDiscount.setPricingRuleReference(fieldNum(RetailPeriodicDiscount, HeaderPricingRule), GUPPricingRule::createRule().RecId);
            }

            if (!periodicDiscountLine.LinePricingRule)
            {
                periodicDiscountLine.setPricingRuleReference(fieldNum(RetailPeriodicDiscountLine, LinePricingRule), GUPPricingRule::createRule().RecId);
            }
        }
        else if (element.showPricingGroupHeader)
        {
            periodicDiscount = argsRecord;

            if (!periodicDiscount.HeaderPricingRule)
            {
                periodicDiscount.setPricingRuleReference(fieldNum(RetailPeriodicDiscount, HeaderPricingRule), GUPPricingRule::createRule().RecId);
            }
        }

        groupCodeHeader = periodicDiscount.HeaderPricingGroupCode;
        groupCodeLine = periodicDiscountLine.LinePricingGroupCode;
    }

    private void initFormPricingObjectPreviewQuery()
    {
        Query inventTableQuery, custTableQuery, productVariantQuery;

        custTableQuery = new Query();
        custTableQuery.addDataSource(tableNum(CustTable))
            .addRange(fieldNum(CustTable, RecId))
            .value(int2Str(-1));

        inventTableQuery = new Query();
        inventTableQuery.addDataSource(tableNum(InventTable))
            .addRange(fieldNum(InventTable, RecId))
            .value(int2Str(-1));

        productVariantQuery = new Query();
        productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
            .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
            .value(int2Str(-1));

        element.inventTablePreviewQuery = inventTableQuery;
        element.custTablePreviewQuery = custTableQuery;
        element.productVariantPreviewQuery = productVariantQuery;
    }

private void initFormControls()
{
    if (element.showPricingGroupHeader)
    {
        PriceAttributeGroupCombinationGroup.visible(false);
        PricingGroupLineTab.visible(false);
        allowEditPricingGroupHeader = !element.checkIfHeaderPriceAttributeGroupIsUsed();
        GUPPricingRule_PricingGroupCode.allowEdit(allowEditPricingGroupHeader);
        GUPPricingRule_PriceAttributeGroup.allowEdit(allowEditPricingGroupHeader && groupCodeHeader == GUPGroupAll::Group);
        element.initCustTablePreview();
    }
    else if (element.showPricingGroupHeaderAndLine)
    {
        PricingGroupHeader.allowEdit(false);
        CustTablePreview.visible(false);
        Checkbox_AppendValueOnLookupHeader.visible(false);
        PricingRuleConditionsHeader.visible(groupCodeHeader == GUPGroupAll::Group);
        Cancel.visible(!periodicDiscountLine.PriceAttributeGroupCombinationRecId);
        element.initInventTablePreview();
    }
}

private void initCustTablePreview()
{
    if (GUPPricingRuleHeader.PriceAttributeGroup)
    {
        element.custTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleHeader).build();
        CustTable_ds.executeQuery();
    }
    else 
    {
        CustTablePreview.visible(false);
        PricingRuleConditionsHeader.visible(false);
    }
}

    private void initInventTablePreview()
    {
        element.addProductvariants = (GUPPricingRuleLine.ExclusionType == GUPPricingRuleExclusionType::ProductVariant);

        if (GUPPricingRuleLine.PriceAttributeGroup)
        {
            if (!element.addProductvariants)
            {
                element.inventTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleLine).build();
                InventTable_ds.executeQuery();
                ProductVariantPreview.visible(false);
            }
            else
            {
                element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleLine).addProductVariants().build();
                EcoResDistinctProductVariant_ds.executeQuery();
                InventTablePreview.visible(false);
            }
        }
        else
        {
            InventTablePreview.visible(false);
            ProductVariantPreview.visible(false);
            PricingRuleConditionsLine.visible(false);
        }
    }

private void updatePricingGroupHeaderControls()
{
    boolean hasPricingGroupHeader = GUPPricingRuleHeader.PriceAttributeGroup != 0;
    GUPPricingRule_PriceAttributeGroup.allowEdit(groupCodeHeader == GUPGroupAll::Group);
    PricingRuleConditionsHeader.visible(hasPricingGroupHeader);
    CustTablePreview.visible(hasPricingGroupHeader);
}

private void updatePricingGroupLineControls()
{
    boolean hasPricingGroupLine = GUPPricingRuleLine.PriceAttributeGroup != 0;
    PricingRuleConditionsLine.visible(hasPricingGroupLine);
    InventTablePreview.visible(hasPricingGroupLine && !element.addProductvariants);
    ProductVariantPreview.visible(hasPricingGroupLine && element.addProductvariants);
}

private void setPriceAttributeGroupCombinationName()
{
    if (element.showPricingGroupHeaderAndLine)
    {
        if (periodicDiscountLine.PriceAttributeGroupCombinationRecId)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination priceAttributeGroupCombination = GUPPriceComponentCodePriceAttributeGroupCombination::find(periodicDiscountLine.PriceAttributeGroupCombinationRecId);
            PriceAttributeGroupCombination_Name.text(priceAttributeGroupCombination.Name);
        }
    }
}

private boolean checkIfHeaderPriceAttributeGroupIsUsed()
{
    RetailPeriodicDiscountLine currentPeriodicDiscountLine;
    select firstonly RecId from currentPeriodicDiscountLine
        where currentPeriodicDiscountLine.offerId == periodicDiscount.OfferId
           && currentPeriodicDiscountLine.PriceAttributeGroupCombinationRecId != 0;
             
    return currentPeriodicDiscountLine.RecId;
}

private void togglePricingRuleIncludeExcludeButtonVisibility(boolean _showExclude, GUPPricingAttributeSourceLevel sourceLevel)
{
    switch (sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            ExcludeCustAcc.visible(_showExclude);
            IncludeCustAcc.visible(!_showExclude);
            break;
        case GUPPricingAttributeSourceLevel::Line:
            ExcludeItemId.visible(_showExclude);
            IncludeItemId.visible(!_showExclude);
            ExcludeProductVariant.visible(_showExclude);
            IncludeProductVariant.visible(!_showExclude);
            break;
    }
}

    private void clearRuleExclusions(GUPPricingRule pricingRule, GUPPricingRuleExclusionType _exclusionType)
    {
        ttsbegin;

        pricingRule.selectForUpdate(true);
        pricingRule.ExclusionType = _exclusionType;
        pricingRule.clearRuleExclusions();
        pricingRule.update();

        ttscommit;
    }

    private void toggleInventTableProductVariantPreviewVisibility(boolean _addProductVariants = addProductvariants)
    {
        element.addProductvariants = _addProductVariants;

        GUPPricingAttributeGroup attributeGroup;
        select firstonly attributeGroup where attributeGroup.RecId == GUPPricingRuleLine.PriceAttributeGroup;

        if (attributeGroup.RecId && 
            attributeGroup.matchSource(GUPPricingAttributeSource::Product))
        {
            InventTablePreview.enabled(!_addProductVariants);
            InventTablePreview.visible(!_addProductVariants);
            ProductVariantPreview.enabled(_addProductVariants);
            ProductVariantPreview.visible(_addProductVariants);

            if (_addProductVariants)
            {
                Query inventTableQuery = new Query();
                inventTableQuery.addDataSource(tableNum(InventTable))
                    .addRange(fieldNum(InventTable, RecId))
                    .value(int2Str(-1));

                element.inventTablePreviewQuery = inventTableQuery;
                element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleLine)
                        .addProductVariants()
                        .build();
                EcoResDistinctProductVariant_ds.executeQuery();
                ProductVariantPreview.fastTabExpanded(FastTabExpanded::Yes);
            }
            else
            {
                Query productVariantQuery = new Query();
                productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
                    .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
                    .value(int2Str(-1));

                element.productVariantPreviewQuery = productVariantQuery;
                element.inventTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleLine)
                        .build();
                InventTable_ds.executeQuery();
            }
        }
    }

    private void modifiedPricingRuleConditionValue(GUPPricingRule pricingRule, GUPPricingRuleCondition pricingRuleCondition, GUPPricingAttributeSourceLevel sourceLevel)
    {
        GUPPricingObjectQueryBuilder queryBuilder = GUPPricingObjectQueryBuilder::constructFromPricingRule(
                pricingRule,
                pricingRuleCondition.RecId,
                pricingRuleCondition.ConditionValue);

        switch (sourceLevel)
        {
            case GUPPricingAttributeSourceLevel::Header:
                element.custTablePreviewQuery = queryBuilder.build();
                CustTable_ds.executeQuery();
                break;
            case GUPPricingAttributeSourceLevel::Line:
                if (element.addProductvariants)
                {
                    element.productVariantPreviewQuery = queryBuilder.addProductVariants().build();
                    EcoResDistinctProductVariant_ds.executeQuery();
                }
                else
                {
                    element.inventTablePreviewQuery = queryBuilder.build();
                    InventTable_ds.executeQuery();
                }
                break;
        }
    }

    private boolean validateCanClose()
    {
        if (!element.formIsCancelled &&
            groupCodeHeader == GUPGroupAll::Group &&
            GUPPricingRule_PriceAttributeGroup.text() == '')
        {
            return checkFailed("@GlobalUnifiedPricing:GUPDoesNotSelectPricingAttributeGroups");
        }

        if (!element.formIsCancelled &&
            PriceAttributeGroupCombinationGroup.isVisible() &&
            PriceAttributeGroupCombination_Name.text() == '')
        {
            return checkFailed("@GlobalUnifiedPricing:GUPDoesNotSelectPriceAttributeGroupCombination");
        }

        return true;
    }

    public void close()
    {
        super();

        if (!element.formIsCancelled)
        {
            ttsbegin;

            if (periodicDiscount.HeaderPricingGroupCode != groupCodeHeader)
            {
                periodicDiscount.selectForUpdate(true);
                periodicDiscount.HeaderPricingGroupCode = groupCodeHeader;
                periodicDiscount.update();
            }

            if (periodicDiscountLine.LinePricingGroupCode != groupCodeLine)
            {
                periodicDiscountLine.selectForUpdate(true);
                periodicDiscountLine.LinePricingGroupCode = groupCodeLine;
                periodicDiscountLine.update();
            }

            ttscommit;
        }
    }

    public boolean closed()
    {
        boolean ret;
    
        ret = super();

        if (element.args().caller() && formHasMethod(element.args().caller(), identifierStr(refreshFormDatasource)))
        {
            if (showPricingGroupHeaderAndLine)
            {
                element.args().caller().refreshFormDatasource(GUPPricingAttributeSourceLevel::Line);
            }
            else if (showPricingGroupHeader)
            {
                element.args().caller().refreshFormDatasource(GUPPricingAttributeSourceLevel::Header);
            }
        }
    
        return ret;
    }

public boolean canClose()
{
    boolean ret;

    ret = super() && this.validateCanClose();

    return ret;
}

        public void init()
        {
            super();

            QueryBuildDataSource qbdsPricingRule = GUPPricingRuleHeader_ds.queryBuildDataSource();

            qbdsPricingRule.clearLinks();
            qbdsPricingRule.clearDynalinks();

            qbdsPricingRule.addDynalink(fieldNum(GUPPricingRule, RecId), periodicDiscount, fieldNum(RetailPeriodicDiscount, HeaderPricingRule));
        }

[SysClientCacheDataMethodAttribute(false)]
public display GUPPricingAttributeSourceLevel sourceLevelHeader(GUPPricingRule _pricingRule)
{
    return GUPPricingAttributeSourceLevel::Header;
}

        public edit GUPGroupAll groupCodeTypeHeader(boolean _set, GUPPricingRule _pricingRule, GUPGroupAll _codeType)
        {
            if (_set)
            {
                groupCodeHeader = _codeType;

                if (_codeType == GUPGroupAll::All)
                {
                    _pricingRule.clearPricingGroup();

                    GUPPricingRuleHeader_ds.research(true);
                }
            }

            return groupCodeHeader;
        }

public void executeQuery()
{
    super();
    Name priceAttributeGroupName = GUPPricingAttributeGroup::find(GUPPricingRuleHeader.PriceAttributeGroup).Name;
    GUPPricingRule_PriceAttributeGroup.text(priceAttributeGroupName);
}

public display Name displayPricingAttributeName(GUPPricingRuleCondition _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

        public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleCondition _ruleCondition, Name _name)
        {
            if (_set)
            {
                _ruleCondition.editConditionValue(_name, Checkbox_AppendValueOnLookupLine.checked());
                _ruleCondition.write();

                element.clearRuleExclusions(GUPPricingRuleHeader, GUPPricingRuleHeader.ExclusionType);
                element.togglePricingRuleIncludeExcludeButtonVisibility(true, GUPPricingAttributeSourceLevel::Header);
                GUPPricingAttributeLineState::clearLineState(tableNum(GUPPricingRule), periodicDiscount.HeaderPricingRule);
            }

            return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                _ruleCondition.priceAttributeLink().AttributeName,
                _ruleCondition.ConditionValue,
                _ruleCondition.priceAttributeLink());
        }

    public void init()
    {
        super();

        QueryBuildDataSource qbdsPricingRule = GUPPricingRuleLine_ds.queryBuildDataSource();

        qbdsPricingRule.clearLinks();
        qbdsPricingRule.clearDynalinks();

        qbdsPricingRule.addDynalink(fieldNum(GUPPricingRule, RecId), periodicDiscountLine, fieldNum(RetailPeriodicDiscountLine, LinePricingRule));
    }

