        public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleCondition _ruleCondition, Name _name)
        {
            if (_set)
            {
                _ruleCondition.ConditionValue = _name;
                _ruleCondition.write();

                element.clearRuleExclusions(GUPPricingRuleLine, GUPPricingRuleLine.ExclusionType);
                element.togglePricingRuleIncludeExcludeButtonVisibility(true, GUPPricingAttributeSourceLevel::Line);
                GUPPricingAttributeLineState::clearLineState(tableNum(GUPPricingRule), periodicDiscountLine.LinePricingRule);
            }

            return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                _ruleCondition.priceAttributeLink().AttributeName,
                _ruleCondition.ConditionValue,
                _ruleCondition.priceAttributeLink());
        }

public void executeQuery()
{
    this.query(element.custTablePreviewQuery);
    super();
}

public display str displayCustTableExclusion(CustTable _custTable)
{
    GUPPricingRuleExclusion excluded;
    select firstonly RecId from excluded where excluded.Exclusion == _custTable.AccountNum && excluded.RuleId == GUPPricingRuleHeader.RecId;

    if (excluded.RecId)
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Exclude";
    }
    else
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Include";
    }
}

public void markChanged()
{
    super();

    MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();
    CustTable custTableExclusion;
    selectionHelper.parmDatasource(CustTable_ds);
    custTableExclusion = selectionHelper.getFirst();

    while (custTableExclusion)
    {
        if (GUPPricingRuleHeader.isExcluded(custTableExclusion.AccountNum))
        {
            element.togglePricingRuleIncludeExcludeButtonVisibility(false, GUPPricingAttributeSourceLevel::Header);
            return;
        }
        custTableExclusion = selectionHelper.getNext();
    }

    element.togglePricingRuleIncludeExcludeButtonVisibility(true, GUPPricingAttributeSourceLevel::Header);
}

public void executeQuery()
{
    this.query(element.inventTablePreviewQuery);
    super();
}

