        public boolean modified()
        {
            boolean ret;
    
            ret = super();

            element.updatePricingGroupHeaderControls();
    
            return ret;
        }

        public void lookup()
        {
            SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPricingAttributeGroup), this);
            Query query = new Query();
            QueryBuildDataSource qbdsGroup = query.addDataSource(tableNum(GUPPricingAttributeGroup));
            qbdsGroup.addRange(fieldNum(GUPPricingAttributeGroup, SourceLevel))
                .value(any2Str(GUPPricingAttributeSourceLevel::Header));
            qbdsGroup.addRange(fieldNum(GUPPricingAttributeGroup, IsValid))
                .value(any2Str(NoYes::Yes));
            qbdsGroup.addRange(fieldNum(GUPPricingAttributeGroup, GroupType))
                .value(enum2Symbol(enumNum(GUPPricingAttributeGroupType), GUPPricingAttributeGroupType::General));

            if (formHasMethod(element.args().caller(), identifierStr(filterAddPriceAttributeGroupQuery)))
            {
                element.args().caller().filterAddPriceAttributeGroupQuery(qbdsGroup, GUPPricingAttributeSourceLevel::Header);
            }

            sysTableLookup.addLookupfield(fieldNum(GUPPricingAttributeGroup, Name));
            sysTableLookup.addLookupfield(fieldNum(GUPPricingAttributeGroup, Description));

            sysTableLookup.parmUseLookupValue(false);
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }

        public boolean modified()
        {
            boolean ret;
        
            ret = super();
            str value = this.valueStr();

            GUPPricingAttributeGroup attributeGroup;
            select firstonly attributeGroup where attributeGroup.Name == value;

            if (attributeGroup.RecId)
            {
                ttsbegin;

                GUPPricingRuleHeader.clearRuleConditions();
                GUPPricingRuleHeader.initPricingRule(attributeGroup);
                
                ttscommit;

                GUPPricingRuleHeader_ds.executeQuery();
                element.custTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleHeader).build();
                CustTable_ds.executeQuery();
            }

            element.updatePricingGroupHeaderControls();
        
            return ret;
        }

        public void lookup()
        {
            GUPPricingAttributeAllowedValueLookup::doLookUp(this, GUPPricingRuleConditionHeader.priceAttributeLink());

            super();
        }

        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            element.modifiedPricingRuleConditionValue(GUPPricingRuleHeader, GUPPricingRuleConditionHeader, GUPPricingAttributeSourceLevel::Header);
        
            return ret;
        }

        public void gotFocus()
        {
            super();
            
            // Prohibit customized input for 'fixed value' or 'referenced' price attribute.
            GUPIPricingAttribute priceAttribute = GUPPricingRuleConditionHeader.pricingAttribute();

            if (priceAttribute.getFixedAllowedValueEnumId() != GUPAbstractPricingAttribute::ENUM_ID_NOT_EXIST
                || priceAttribute.getDataType() == AttributeDataType::Reference)
            {
                GUPPricingRuleCondition_ConditionValue.lookupOnly(true);
            }
            else
            {
                GUPPricingRuleCondition_ConditionValue.lookupOnly(false);
            }
       
            this.replaceOnLookup(true);
        }

    public void clicked()
    {
        MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();
        CustTable custTableExclusion;
        selectionHelper.parmDatasource(CustTable_ds);
        custTableExclusion = selectionHelper.getFirst();

        ttsbegin;

        while (custTableExclusion)
        {
            GUPPricingRuleHeader.exclude(custTableExclusion.AccountNum);
            custTableExclusion = selectionHelper.getNext();
        }

        ttscommit;

        CustTable_ds.executeQuery();
    }

