        public void lookup()
        {
            SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination), this);
            Query query = new Query();
            QueryBuildDataSource qbdsGroup = query.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));

            if (periodicDiscount.HeaderPricingGroupCode == GUPGroupAll::Group)
            {
                qbdsGroup.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroup))
                         .value(any2Str(GUPPricingRuleHeader.PriceAttributeGroup));
                qbdsGroup.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll))
                    .value(enum2Symbol(enumNum(GUPGroupAll), GUPGroupAll::Group));
            }
            else
            {
                qbdsGroup.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll))
                         .value(enum2Symbol(enumNum(GUPGroupAll), GUPGroupAll::All));
            }

            qbdsGroup.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, PriceComponentCode))
                     .value(any2Str(periodicDiscount.PriceComponentCode));
			qbdsGroup.addOrderByField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority), SortOrder::Descending);

            sysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Name), true);
            sysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroup));
            sysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroup));
            sysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority));

            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }

        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            GUPPriceComponentCodePriceAttributeGroupCombination priceAttributeGroupCombination;

            select firstonly RecId, LinePriceAttributeGroup, HeaderGroupAll, LineGroupAll from priceAttributeGroupCombination
                where priceAttributeGroupCombination.Name == this.valueStr()
                   && priceAttributeGroupCombination.PriceComponentCode == periodicDiscount.PriceComponentCode;

            if (priceAttributeGroupCombination.RecId &&
                periodicDiscountLine.PriceAttributeGroupCombinationRecId != priceAttributeGroupCombination.RecId)
            {
                if (periodicDiscountLine.RecId)
                {
                    ttsbegin;

                    periodicDiscountLine.selectForUpdate(true);
                    periodicDiscountLine.PriceAttributeGroupCombinationRecId = priceAttributeGroupCombination.RecId;
                    periodicDiscountLine.update();

                    ttscommit;
                }
                else
                {
                    periodicDiscountLine.PriceAttributeGroupCombinationRecId = priceAttributeGroupCombination.RecId;
                }

                groupCodeHeader = priceAttributeGroupCombination.HeaderGroupAll;
                groupCodeLine = priceAttributeGroupCombination.LineGroupAll;

                if (groupCodeLine == GUPGroupAll::Group &&
                    GUPPricingRuleLine.PriceAttributeGroup != priceAttributeGroupCombination.LinePriceAttributeGroup)
                {
                    GUPPricingRule_PricingGroupCode.selection(enum2int(GUPGroupAll::Group));

                    ttsbegin;

                    GUPPricingRuleLine.clearRuleConditions();
                    GUPPricingRuleLine.initPricingRule(GUPPricingAttributeGroup::find(priceAttributeGroupCombination.LinePriceAttributeGroup));
            
                    ttscommit;

                    GUPPricingRuleLine_ds.research(true);

                    element.toggleInventTableProductVariantPreviewVisibility(element.addProductvariants);
                }
                else if (groupCodeLine == GUPGroupAll::All)
                {
                    GUPPricingRule_PricingGroupCode.selection(enum2int(GUPGroupAll::All));
                    GUPPricingRuleLine.clearPricingGroup();

                    GUPPricingRuleLine_ds.research(true);
                }

                element.updatePricingGroupLineControls();
            }

            return ret;
        }

        public void lookup()
        {
            GUPPricingAttributeAllowedValueLookup::doLookUp(this, GUPPricingRuleConditionLine.priceAttributeLink());

            super();
        }

        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            element.modifiedPricingRuleConditionValue(GUPPricingRuleLine, GUPPricingRuleConditionLine, GUPPricingAttributeSourceLevel::Line);
        
            return ret;
        }

        public void gotFocus()
        {
            super();
            
            // Prohibit customized input for 'fixed value' or 'referenced' price attribute.
            GUPIPricingAttribute priceAttribute = GUPPricingRuleConditionLine.pricingAttribute();

            if (priceAttribute.getFixedAllowedValueEnumId() != GUPAbstractPricingAttribute::ENUM_ID_NOT_EXIST
                || priceAttribute.getDataType() == AttributeDataType::Reference)
            {
                GUPPricingRuleConditionLine_ConditionValue.lookupOnly(true);
            }
            else
            {
                GUPPricingRuleConditionLine_ConditionValue.lookupOnly(false);
            }
       
            this.replaceOnLookup(true);
        }

