    public void clicked()
    {
        // TODO: NoYes dialog confirm
        Query previewQuery =
            GUPPricingObjectQueryBuilder::constructFromPricingRule(GUPPricingRuleLine)
                .addProductVariants()
                .build();
        QueryRun qr = new QueryRun(previewQuery);
        qr.next();
        Common first = qr.getNo(1);

        if (first.RecId)
        {
            element.clearRuleExclusions(GUPPricingRuleLine, GUPPricingRuleExclusionType::ProductVariant);
            element.toggleInventTableProductVariantPreviewVisibility(true);
        }
        else
        {
            warning("@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_AllVariants_NoVariant");
        }
    }

